      const a = (i / 6) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * b.r * 1.25, Math.sin(a) * b.r * 1.25);
      ctx.lineTo(Math.cos(a) * b.r * 1.55, Math.sin(a) * b.r * 1.55);
      ctx.stroke();
