/* Mosslight Courier page shell: a letterboxed 16:9 canvas on a deep navy
   backdrop. All game visuals are drawn by the renderer; this only sizes it. */

:root {
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #04070f;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  font-family: system-ui, sans-serif;
}

.stage {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

canvas#game {
  width: min(100vw, calc(100vh * 16 / 9));
  height: min(100vh, calc(100vw * 9 / 16));
  background: #070d20;
  touch-action: none;
  border-radius: min(1.2vw, 10px);
  box-shadow:
    0 0 70px rgba(94, 225, 190, 0.08),
    0 24px 70px rgba(0, 0, 0, 0.55);
  cursor: crosshair;
}

.noscript {
  color: #9fb6d8;
  text-align: center;
  font-size: 16px;
}
```
